  if (/^[1-9]$/.test(e.key)) { input(Number(e.key)); return; }
  if (e.key === "Backspace" || e.key === "Delete" || e.key === "0") { root.querySelector(".erase").click(); return; }
  if (e.key.toLowerCase() === "n") { notesMode = !notesMode; render(); return; }
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "z") { e.preventDefault(); root.querySelector(".undo").click(); return; }
