const gridEl = root.querySelector(".cw-grid");
let cellEls = [];

const wordAt = (i, d) => puzzle.words.find((p) => p.dir === d && (d === "across" ? p.y === ((i / puzzle.w) | 0) && i % puzzle.w >= p.x && i % puzzle.w < p.x + p.word.length : p.x === i % puzzle.w && ((i / puzzle.w) | 0) >= p.y && ((i / puzzle.w) | 0) < p.y + p.word.length));
